; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_dec
kw_dec:
			movea.l (sp)+, a0
			subq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			move.l (sp)+, d0
			movea.l (sp)+, a1
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scplevv ntc_cmp
kw_scplevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sgt

			even
;## kw_scpgevv ntc_cmp
kw_scpgevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sge

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			bra ntc_strcpy_lp

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printtab ntc_data ntc_plat_screen
;kw_printtab, <nvar>  - Tab(n) in Print: spaces up to column n (1 based),
;  a new line first when the cursor is already past it. n off the line: nothing
kw_printtab:
			movea.l (sp)+, a0
			move.w (a0), d2
			subq.w #1, d2
ntc_pt_go:						; d2 = the column (0 based)
			moveq #0, d0
			move.b ntc_scols, d0
			cmp.w d0, d2
			bcc ntc_pt_end			; (also below 0: unsigned)
			NTC_RS
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bcc ntc_pt_lp
			jsr ntc_plat_newline
ntc_pt_lp:
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bls ntc_pt_done
			moveq #' ', d0
			jsr ntc_plat_putc
			bra ntc_pt_lp
ntc_pt_done:
			NTC_TS
ntc_pt_end:
			rts

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src
kw_psets:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pss_a, a6
			bra ntc_paddr
kw_pss_a:
			movea.l a0, a1
			movea.l (sp)+, a0
			subq.w #1, d1
			bra ntc_strcpy_lp

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			movea.l (sp)+, a0
			move.w 2(a0), d0
			add.w 6(a0), d0
			subq.w #1, d0
			movea.l (sp)+, a1
			move.w d0, (a1)
			rts

; ============================================================
; Long (32 bit signed): a 68000 long. Every argument is an address
; (a literal is a dc.l in the ROM).
; ============================================================

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## kw_l_add
kw_l_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			add.l (a1), d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## ntc_ltoa ntc_data
; the Long d0 to text at a1, a 0 at the end (a1 on it). jmp (a6). Uses d0-d3, a0
ntc_ltoa:
			tst.l d0
			bpl ntc_lta_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_lta_pos:
			lea ntc_lta_tmp+12, a0
			clr.b -(a0)
ntc_lta_lp:
			; d0 unsigned / 10: high word first
			move.l d0, d2
			clr.w d2
			swap d2
			divu.w #10, d2				; d2 = rem:quot of the high word
			move.w d2, d3				; the quotient's high word
			move.w d0, d2				; rem (high) : low word
			divu.w #10, d2
			swap d3
			move.w d2, d3				; d3 = the quotient
			swap d2
			addi.b #'0', d2
			move.b d2, -(a0)
			move.l d3, d0
			bne ntc_lta_lp
ntc_lta_cp:
			move.b (a0)+, (a1)+
			bne ntc_lta_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_l_print ntc_ltoa ntc_printbuf
kw_l_print:
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_numbuf, a1
			lea kw_lpr_b, a6
			bra ntc_ltoa
kw_lpr_b:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_cls:
			jmp ntc_ti89_clear

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_i:			dc.w 0
ad_arr_nums:			dc.w (arr_nums)&$FFFF, (0)&$FFFF, (0)&$FFFF, (6)&$FFFF, (1)&$FFFF, (2)&$FFFF		; array as an argument
var_total_total:			dc.w 0
ad_arr_odd:			dc.w (arr_odd)&$FFFF, (1)&$FFFF, (0)&$FFFF, (4)&$FFFF, (1)&$FFFF, (2)&$FFFF		; array as an argument
var_lo_lo:			dc.w 0
var_hi_hi:			dc.w 0
var_count_count:			dc.w 0
ad_arr_words:			dc.w (arr_words)&$FFFF, (0)&$FFFF, (0)&$FFFF, (3)&$FFFF, (1)&$FFFF, (41)&$FFFF		; array as an argument
			dc.b 40			; capacity
var_longest_longest:			ds.b 41
			even
ad_arr_big:			dc.w (arr_big)&$FFFF, (0)&$FFFF, (0)&$FFFF, (4)&$FFFF, (1)&$FFFF, (4)&$FFFF		; array as an argument
var_bigsum_bigsum:			dc.l 0
var_t:			dc.w 0
var_bad:			dc.w 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
p_chks_rs:			dc.l 0
			dc.b 40			; capacity
var_chks_got:			ds.b 41
			even
			dc.b 40			; capacity
var_chks_want:			ds.b 41
			even
p_chkl_rs:			dc.l 0
var_chkl_got:			dc.l 0
var_chkl_want:			dc.l 0
p_total_rs:			dc.l 0
var_total_k:			dc.w 0
for6_l:			dc.w 0
p_sortup_rs:			dc.l 0
var_sortup_k:			dc.w 0
var_sortup_j:			dc.w 0
var_sortup_v:			dc.w 0
for7_l:			dc.w 0
p_lo_rs:			dc.l 0
p_hi_rs:			dc.l 0
p_count_rs:			dc.l 0
p_longest_rs:			dc.l 0
var_longest_k:			dc.w 0
for10_l:			dc.w 0
p_shout_rs:			dc.l 0
var_shout_k:			dc.w 0
for12_l:			dc.w 0
p_bigsum_rs:			dc.l 0
var_bigsum_k:			dc.w 0
for13_l:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
			dc.b 40			; capacity
stmp2:			ds.b 41
			even
ltmp0:			dc.l 0
ltmp1:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_lta_tmp:	ds.b 12
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_nums		equ ntc_bss + 0		; 12 bytes
arr_odd		equ ntc_bss + 12		; 8 bytes
arr_words		equ ntc_bss + 20		; 123 bytes
arr_big		equ ntc_bss + 144		; 16 bytes
arr_grid		equ ntc_bss + 160		; 24 bytes
pa_total_a		equ ntc_bss + 184		; 12 bytes
pa_sortup_a		equ ntc_bss + 196		; 12 bytes
pa_lo_a		equ ntc_bss + 208		; 12 bytes
pa_hi_a		equ ntc_bss + 220		; 12 bytes
pa_count_a		equ ntc_bss + 232		; 12 bytes
pa_longest_s		equ ntc_bss + 244		; 12 bytes
pa_shout_s		equ ntc_bss + 256		; 12 bytes
pa_bigsum_v		equ ntc_bss + 268		; 12 bytes
ntc_bss_size	equ 280
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
